def transform(grid):
    g=[row[:] for row in grid]; H,W=len(g),len(g[0])
    bg=g[0][0]
    cells=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg]
    # find diagonal adjacent same-color pair (dr=+1, dc=-1)
    from collections import defaultdict
    pos=defaultdict(list)
    for r,c,v in cells: pos[v].append((r,c))
    for v,ps in pos.items():
        s=set(ps)
        for (r,c) in ps:
            if (r+1,c-1) in s:
                # extend down-left from (r+1,c-1)
                rr,cc=r+2,c-2
                while 0<=rr<H and 0<=cc<W:
                    g[rr][cc]=v; rr+=1; cc-=1
    return g

